input.command:
mkdir -p /git /var/www/main /var/www/dev /etc/nginx/ssl /run/sshd
id git >/dev/null 2>&1 || useradd -m -s /bin/bash git
echo 'git:password' | chpasswd
chown -R git:git /git
chmod 755 /git
if [ ! -d /git/project ]; then
  git init --bare /git/project
fi
chown -R git:git /git/project
cat > /git/project/hooks/post-receive <<'EOF'
#!/bin/bash
set -e
REPO=/git/project
export GIT_DIR="$REPO"
while read oldrev newrev refname; do
  case "$refname" in
    refs/heads/main)
      dest=/var/www/main
      ;;
    refs/heads/dev)
      dest=/var/www/dev
      ;;
    *)
      continue
      ;;
  esac
  mkdir -p "$dest"
  find "$dest" -mindepth 1 -delete
  git archive "$newrev" | tar -x -C "$dest"
done
exit 0
EOF
chmod +x /git/project/hooks/post-receive
chown git:git /git/project/hooks/post-receive
openssl req -x509 -nodes -newkey rsa:2048 -days 3650 \
  -keyout /etc/nginx/ssl/server.key -out /etc/nginx/ssl/server.crt \
  -subj "/CN=localhost" 2>/dev/null
chmod 600 /etc/nginx/ssl/server.key
cat > /etc/nginx/sites-available/gitdeploy <<'EOF'
server {
    listen 8443 ssl;
    server_name localhost;

    ssl_certificate     /etc/nginx/ssl/server.crt;
    ssl_certificate_key /etc/nginx/ssl/server.key;
    ssl_protocols       TLSv1.2 TLSv1.3;

    root /var/www/main;
    index index.html;

    location /dev/ {
        alias /var/www/dev/;
        index index.html;
    }
}
EOF
ln -sf /etc/nginx/sites-available/gitdeploy /etc/nginx/sites-enabled/gitdeploy
rm -f /etc/nginx/sites-enabled/default
nginx -t
